<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useDialog, useMessage } from 'naive-ui'
import ShareDialog from '../components/ShareDialog.vue'
import { api } from '../services/api'

interface ImageItem {id:number;filename?:string;display_name?:string;url:string;share_url?:string;caption?:string;category?:string;tags?:string;resource_url?:string;folder_id?:number|null;size?:number;storage?:string;created_at:string}
interface ImageCategory {id:number;category:'image_category';label:string;value:string;color?:string|null;sort_order:number;is_active:number|boolean;image_count:number}
interface ImageFolder {id:number;name:string;color:string;sort_order:number;image_count:number;total_bytes:number}
type ShareTarget={type:'image'|'folder';id:number;title:string}

const ALL='__all__',UNCATEGORIZED='__uncategorized__',ROOT='__root__',limit=24
const message=useMessage(),dialog=useDialog(),loading=ref(false),uploading=ref(false),dragging=ref(false),images=ref<ImageItem[]>([]),categories=ref<ImageCategory[]>([]),folders=ref<ImageFolder[]>([]),total=ref(0),totalBytes=ref(0),page=ref(1),query=ref(''),categoryFilter=ref(ALL),folderFilter=ref<string>(ALL)
const categorySummary=reactive({total:0,unclassified:0}),folderSummary=reactive({root:0}),showEdit=ref(false),showCategories=ref(false),showFolders=ref(false),showFolderDelete=ref(false),showShare=ref(false),categorySaving=ref(false),folderSaving=ref(false),folderDeleting=ref(false),editing=ref<ImageItem|null>(null),editingCategoryId=ref<number|null>(null),editingFolderId=ref<number|null>(null),deletingFolder=ref<ImageFolder|null>(null),folderDeleteMode=ref<'delete'|'keep'>('delete'),draggedImageId=ref<number|null>(null),shareTarget=ref<ShareTarget|null>(null)
const uploadMeta=reactive({caption:'',category:'',tags:'',resource_url:'',folder_id:null as number|null}),editForm=reactive({display_name:'',caption:'',category:'',tags:'',resource_url:'',folder_id:null as number|null}),categoryForm=reactive({name:'',color:'#3ec9c5'}),folderForm=reactive({name:'',color:'#3ec9c5'})
const visibleCategories=computed(()=>categories.value.filter(item=>Boolean(item.is_active)||Number(item.image_count)>0)),categoryOptions=computed(()=>categories.value.filter(item=>Boolean(item.is_active)).map(item=>({label:item.label,value:item.value}))),folderOptions=computed(()=>[{label:'根目录',value:0},...folders.value.map(item=>({label:item.name,value:item.id}))])
let searchTimer:number|undefined
const jobPolls=new Set<number>()
function monitorJob(jobId:string,successText:string){
  const timer=window.setInterval(async()=>{try{const job=await api.get<any>(`/maintenance-jobs/${jobId}`);if(job.status==='completed'){clearInterval(timer);jobPolls.delete(timer);message.success(successText);await refresh()}else if(job.status==='failed'){clearInterval(timer);jobPolls.delete(timer);message.error(job.error||'后台任务失败');await refresh()}}catch{clearInterval(timer);jobPolls.delete(timer)}},2000)
  jobPolls.add(timer)
}
function size(bytes=0){if(bytes<1024)return`${bytes} B`;if(bytes<1048576)return`${(bytes/1024).toFixed(1)} KB`;return`${(bytes/1048576).toFixed(1)} MB`}
function categoryMeta(value?:string){return categories.value.find(item=>item.value===value)}
function categoryLabel(value?:string){return categoryMeta(value)?.label||value||'未分类'}
function folderName(id?:number|null){return folders.value.find(item=>item.id===id)?.name||'根目录'}
async function loadImages(){loading.value=true;try{const params=new URLSearchParams({page:String(page.value),limit:String(limit)});if(query.value)params.set('q',query.value);if(categoryFilter.value!==ALL)params.set('category',categoryFilter.value);if(folderFilter.value!==ALL)params.set('folder',folderFilter.value);const data=await api.get<any>(`/images?${params}`);images.value=data.images||[];total.value=data.total||0;totalBytes.value=data.total_bytes||0}finally{loading.value=false}}
async function loadCategories(){const data=await api.get<any>('/images/categories');categories.value=data.categories||[];categorySummary.total=data.total||0;categorySummary.unclassified=data.unclassified_count||0}
async function loadFolders(){const data=await api.get<any>('/image-folders');folders.value=data.folders||[];folderSummary.root=data.root_count||0}
async function refresh(){await Promise.all([loadImages(),loadCategories(),loadFolders()])}
function selectCategory(value:string){categoryFilter.value=value;page.value===1?void loadImages():page.value=1}
function selectFolder(value:string){folderFilter.value=value;uploadMeta.folder_id=value===ALL||value===ROOT?null:Number(value);page.value===1?void loadImages():page.value=1}
function scheduleLoad(){clearTimeout(searchTimer);searchTimer=window.setTimeout(()=>{page.value===1?void loadImages():page.value=1},250)}
async function uploadFiles(files:File[],folderId:number|null=uploadMeta.folder_id){if(!files.length)return;uploading.value=true;let done=0;try{for(const file of files){if(!file.type.startsWith('image/')){message.warning(`${file.name} 不是图片`);continue}if(file.size>10*1024*1024){message.error(`${file.name} 超过 10MB`);continue}const body=new FormData();body.append('file',file);body.append('caption',uploadMeta.caption);body.append('category',uploadMeta.category);body.append('tags',uploadMeta.tags);body.append('resource_url',uploadMeta.resource_url);if(folderId)body.append('folder_id',String(folderId));await api.upload('/upload',body);done++}if(done)message.success(`成功上传 ${done} 张图片到${folderName(folderId)}`);page.value=1;await refresh()}finally{uploading.value=false}}
function pick(event:Event){const input=event.target as HTMLInputElement;void uploadFiles(Array.from(input.files||[]));input.value=''}
function dropUpload(event:DragEvent){dragging.value=false;void uploadFiles(Array.from(event.dataTransfer?.files||[]))}
function imageDragStart(event:DragEvent,item:ImageItem){draggedImageId.value=item.id;event.dataTransfer?.setData('application/x-trading-image-id',String(item.id));if(event.dataTransfer)event.dataTransfer.effectAllowed='move'}
async function dropOnFolder(event:DragEvent,folderId:number|null){const files=Array.from(event.dataTransfer?.files||[]);if(files.length){await uploadFiles(files,folderId);return}const id=Number(event.dataTransfer?.getData('application/x-trading-image-id')||draggedImageId.value);draggedImageId.value=null;if(!Number.isInteger(id)||id<=0)return;await api.put('/images/move',{image_ids:[id],folder_id:folderId});message.success(`图片已移动到${folderName(folderId)}`);await refresh()}
function openShare(type:'image'|'folder',id:number,title:string){shareTarget.value={type,id,title};showShare.value=true}
function openEdit(item:ImageItem){editing.value=item;Object.assign(editForm,{display_name:item.display_name||item.filename||'',caption:item.caption||'',category:item.category||'',tags:item.tags||'',resource_url:item.resource_url||'',folder_id:item.folder_id||null});showEdit.value=true}
async function saveEdit(){if(!editing.value)return;await api.put(`/images/${editing.value.id}`,{...editForm,folder_id:editForm.folder_id||null});message.success('图片信息已更新');showEdit.value=false;await refresh()}
function removeImage(item:ImageItem){dialog.warning({title:'永久删除图片',content:'数据库记录、存储对象、交易引用和该图片的分享都会清除，确定继续吗？',positiveText:'删除',negativeText:'取消',async onPositiveClick(){try{await api.del(`/images/${item.id}`);message.success('图片已删除');await refresh()}catch(error){message.error(error instanceof Error?error.message:'图片删除失败')}}})}
function openCategoryManager(){editingCategoryId.value=null;Object.assign(categoryForm,{name:'',color:'#3ec9c5'});showCategories.value=true}
function editCategory(item:ImageCategory){editingCategoryId.value=item.id;Object.assign(categoryForm,{name:item.label,color:item.color||'#3ec9c5'})}
function cancelCategoryEdit(){editingCategoryId.value=null;Object.assign(categoryForm,{name:'',color:'#3ec9c5'})}
async function saveCategory(){const name=categoryForm.name.trim();if(!name)return message.error('请输入分类名称');if(name.length>60)return message.error('分类名称最多 60 个字符');categorySaving.value=true;try{const current=editingCategoryId.value?categories.value.find(item=>item.id===editingCategoryId.value):undefined,payload={category:'image_category',label:name,value:name,color:categoryForm.color,sort_order:current?.sort_order??categories.value.length,is_active:current?Boolean(current.is_active):true};if(current){await api.put(`/settings/${current.id}`,payload);if(categoryFilter.value===current.value)categoryFilter.value=name;if(uploadMeta.category===current.value)uploadMeta.category=name;if(editForm.category===current.value)editForm.category=name;message.success('分类已更新，已有图片已同步')}else{await api.post('/settings',payload);uploadMeta.category=name;message.success('分类已创建')}cancelCategoryEdit();await refresh()}finally{categorySaving.value=false}}
async function toggleCategory(item:ImageCategory,active:boolean){await api.put(`/settings/${item.id}`,{is_active:active});await loadCategories();message.success(active?'分类已启用':'分类已停用')}
function removeCategory(item:ImageCategory){dialog.warning({title:'删除图片分类',content:item.image_count?`“${item.label}”中有 ${item.image_count} 张图片。图片会保留并转为未分类，是否继续？`:`确定删除“${item.label}”分类吗？`,positiveText:'删除分类',negativeText:'取消',async onPositiveClick(){await api.del(`/settings/${item.id}`);if(categoryFilter.value===item.value)categoryFilter.value=UNCATEGORIZED;if(uploadMeta.category===item.value)uploadMeta.category='';if(editForm.category===item.value)editForm.category='';message.success('分类已删除');await refresh()}})}
function openFolderManager(){editingFolderId.value=null;Object.assign(folderForm,{name:'',color:'#3ec9c5'});showFolders.value=true}
function editFolder(item:ImageFolder){editingFolderId.value=item.id;Object.assign(folderForm,{name:item.name,color:item.color})}
function cancelFolderEdit(){editingFolderId.value=null;Object.assign(folderForm,{name:'',color:'#3ec9c5'})}
async function saveFolder(){const name=folderForm.name.trim();if(!name)return message.error('请输入文件夹名称');folderSaving.value=true;try{if(editingFolderId.value){await api.put(`/image-folders/${editingFolderId.value}`,folderForm);message.success('文件夹已更新')}else{const result=await api.post<{id:number}>('/image-folders',folderForm);message.success('文件夹已创建');folderFilter.value=String(result.id);uploadMeta.folder_id=result.id}cancelFolderEdit();await refresh()}finally{folderSaving.value=false}}
function removeFolder(item:ImageFolder){deletingFolder.value=item;folderDeleteMode.value='delete';showFolderDelete.value=true}
async function confirmRemoveFolder(){const item=deletingFolder.value;if(!item)return;folderDeleting.value=true;try{const result=await api.del<any>(`/image-folders/${item.id}?mode=${folderDeleteMode.value}`);if(folderFilter.value===String(item.id))folderFilter.value=folderDeleteMode.value==='keep'?ROOT:ALL;if(uploadMeta.folder_id===item.id)uploadMeta.folder_id=null;showFolderDelete.value=false;if(result.job_id){message.info('文件夹删除已进入后台，可安全离开页面');monitorJob(result.job_id,`文件夹和其中 ${item.image_count} 张图片已永久删除`)}else{message.success('文件夹已删除，图片已移回根目录');await refresh()}}catch(error){message.error(error instanceof Error?error.message:'文件夹删除失败')}finally{folderDeleting.value=false}}
async function reconcile(){const result=await api.post<any>('/images/reconcile',{});message.info('存储对账已进入后台');if(result.job_id)monitorJob(result.job_id,'存储对账完成');else await refresh()}
watch(page,loadImages);onMounted(refresh);onBeforeUnmount(()=>jobPolls.forEach(timer=>clearInterval(timer)))
</script>

<template>
  <section class="page">
    <header class="page-head"><div><h1>图片图床</h1><p>文件夹整理、拖拽移动、分类检索与安全分享</p></div><div class="page-actions"><n-button @click="openFolderManager">管理文件夹</n-button><n-button @click="openCategoryManager">管理分类</n-button><n-button @click="reconcile">同步 R2</n-button></div></header>
    <div class="image-upload panel"><label class="drop-zone" :class="{dragging}" @dragenter.prevent="dragging=true" @dragover.prevent @dragleave.prevent="dragging=false" @drop.prevent="dropUpload"><input type="file" multiple accept="image/png,image/jpeg,image/gif,image/webp" @change="pick"><span class="upload-plus">＋</span><div><strong>{{uploading?'正在上传':'点击或拖拽图片到这里'}}</strong><small>上传至{{folderName(uploadMeta.folder_id)}} · 单张最大 10MB</small></div></label><div class="upload-meta"><n-select v-model:value="uploadMeta.folder_id" clearable :options="folderOptions" placeholder="上传到文件夹"/><n-select v-model:value="uploadMeta.category" clearable :options="categoryOptions" placeholder="选择分类（可选）"/><n-input v-model:value="uploadMeta.tags" placeholder="标签，例如：黄金,1H,做多"/><n-input v-model:value="uploadMeta.caption" placeholder="备注（可选）"/><n-input v-model:value="uploadMeta.resource_url" placeholder="关联视频/网盘资料链接（可选）"/></div></div>
    <section class="folder-shelf panel"><header><div><strong>文件夹</strong><small>把下方图片拖到文件夹即可移动；也可以把电脑图片直接拖到文件夹上传</small></div><n-button size="tiny" @click="openFolderManager">＋ 新建</n-button></header><div class="folder-row"><article :class="{active:folderFilter===ALL}" @click="selectFolder(ALL)"><span class="folder-icon">▱</span><div><strong>全部图片</strong><small>{{categorySummary.total}} 张</small></div></article><article class="folder-drop" :class="{active:folderFilter===ROOT}" @click="selectFolder(ROOT)" @dragover.prevent @drop.prevent.stop="dropOnFolder($event,null)"><span class="folder-icon">▰</span><div><strong>根目录</strong><small>{{folderSummary.root}} 张</small></div></article><article v-for="folder in folders" :key="folder.id" class="folder-drop" :class="{active:folderFilter===String(folder.id)}" :style="{'--folder-color':folder.color}" @click="selectFolder(String(folder.id))" @dragover.prevent @drop.prevent.stop="dropOnFolder($event,folder.id)"><span class="folder-icon">▰</span><div><strong>{{folder.name}}</strong><small>{{folder.image_count}} 张 · {{size(folder.total_bytes)}}</small></div><button title="一键分享文件夹" @click.stop="openShare('folder',folder.id,folder.name)">分享</button></article></div></section>
    <nav class="image-category-tabs panel" aria-label="图片分类"><button :class="{active:categoryFilter===ALL}" @click="selectCategory(ALL)"><span>全部分类</span><b>{{categorySummary.total}}</b></button><button v-for="item in visibleCategories" :key="item.id" :class="{active:categoryFilter===item.value}" :style="{'--category-color':item.color||'#3ec9c5'}" @click="selectCategory(item.value)"><i/><span>{{item.label}}</span><b>{{item.image_count}}</b></button><button :class="{active:categoryFilter===UNCATEGORIZED}" @click="selectCategory(UNCATEGORIZED)"><span>未分类</span><b>{{categorySummary.unclassified}}</b></button><button class="category-add" @click="openCategoryManager">＋ 新建分类</button></nav>
    <div class="image-library-tools"><n-input v-model:value="query" clearable placeholder="搜索名称、备注或标签" @input="scheduleLoad"/><span>{{total}} 张结果 · {{size(totalBytes)}}</span></div>
    <n-spin :show="loading"><div v-if="images.length" class="image-grid"><article v-for="item in images" :key="item.id" class="image-card" draggable="true" @dragstart="imageDragStart($event,item)"><a :href="item.url" target="_blank" rel="noopener"><img :src="item.url" loading="lazy"></a><div><strong :title="item.display_name||item.filename">{{item.display_name||item.filename||'未命名图片'}}</strong><div class="image-badges"><button v-if="item.category" class="image-card-category" :style="{'--category-color':categoryMeta(item.category)?.color||'#3ec9c5'}" @click="selectCategory(item.category)">{{categoryLabel(item.category)}}</button><small>{{folderName(item.folder_id)}} · {{size(item.size)}} · {{item.created_at?.slice(0,10)}}</small></div><p v-if="item.caption">{{item.caption}}</p><small v-if="item.tags"># {{item.tags}}</small><a v-if="item.resource_url" class="image-resource-link" :href="item.resource_url" target="_blank" rel="noopener">打开关联资料 ↗</a><n-space><n-button size="tiny" type="primary" ghost @click="openShare('image',item.id,item.display_name||item.filename||'图片')">分享</n-button><n-button size="tiny" tag="a" :href="item.url" target="_blank">查看</n-button><n-button size="tiny" @click="openEdit(item)">整理</n-button><n-button size="tiny" type="error" ghost @click="removeImage(item)">删除</n-button></n-space></div></article></div><div v-else class="panel empty-box"><strong>暂无匹配图片</strong><p>可切换文件夹或分类，或上传图片。</p></div></n-spin>
    <div v-if="total>limit" class="image-pager"><n-pagination v-model:page="page" :page-count="Math.ceil(total/limit)"/></div>
    <n-modal v-model:show="showEdit" preset="card" title="整理图片" class="form-modal"><n-form label-placement="top"><n-form-item label="显示名称"><n-input v-model:value="editForm.display_name"/></n-form-item><n-grid responsive="screen" cols="1 s:2" :x-gap="12"><n-form-item-gi label="文件夹"><n-select v-model:value="editForm.folder_id" clearable :options="folderOptions"/></n-form-item-gi><n-form-item-gi label="分类"><n-select v-model:value="editForm.category" clearable :options="categoryOptions" placeholder="未分类"/></n-form-item-gi></n-grid><n-form-item label="标签"><n-input v-model:value="editForm.tags"/></n-form-item><n-form-item label="备注"><n-input v-model:value="editForm.caption" type="textarea" :rows="3"/></n-form-item><n-form-item label="关联视频 / 网盘资料"><n-input v-model:value="editForm.resource_url"/></n-form-item><div class="modal-actions"><n-button @click="showEdit=false">取消</n-button><n-button type="primary" @click="saveEdit">保存</n-button></div></n-form></n-modal>
    <n-modal v-model:show="showFolders" preset="card" title="管理文件夹" class="category-modal"><p class="category-help">文件夹用于物理整理，分类用于内容检索。删除时可选择同时永久删除图片，或把图片保留到根目录。</p><div class="category-editor panel"><n-input v-model:value="folderForm.name" maxlength="60" show-count placeholder="文件夹名称" @keyup.enter="saveFolder"/><n-color-picker v-model:value="folderForm.color" :show-alpha="false"/><n-button type="primary" :loading="folderSaving" @click="saveFolder">{{editingFolderId?'保存':'创建'}}</n-button><n-button v-if="editingFolderId" @click="cancelFolderEdit">取消</n-button></div><div v-if="folders.length" class="category-manager-list"><div v-for="folder in folders" :key="folder.id"><i :style="{background:folder.color}"/><div><strong>{{folder.name}}</strong><small>{{folder.image_count}} 张图片 · {{size(folder.total_bytes)}}</small></div><n-button size="tiny" @click="openShare('folder',folder.id,folder.name)">分享</n-button><n-button size="tiny" @click="editFolder(folder)">改名</n-button><n-button size="tiny" type="error" ghost @click="removeFolder(folder)">删除</n-button></div></div></n-modal>
    <n-modal v-model:show="showFolderDelete" preset="card" title="删除文件夹" class="folder-delete-modal" :mask-closable="!folderDeleting">
      <template v-if="deletingFolder"><p>“{{deletingFolder.name}}”中有 {{deletingFolder.image_count}} 张图片，请选择删除方式：</p><n-radio-group v-model:value="folderDeleteMode" class="folder-delete-options"><n-radio value="delete"><strong>删除文件夹和全部图片</strong><small>永久清除图片文件、数据库记录、交易引用和相关分享，无法恢复。</small></n-radio><n-radio value="keep"><strong>仅删除文件夹</strong><small>图片不会增加或复制，只会统一移回根目录；文件夹分享会失效。</small></n-radio></n-radio-group><n-alert v-if="folderDeleteMode==='delete'" type="error" :bordered="false">这是永久操作，请确认这些图片不再需要。</n-alert><div class="modal-actions"><n-button :disabled="folderDeleting" @click="showFolderDelete=false">取消</n-button><n-button :type="folderDeleteMode==='delete'?'error':'primary'" :loading="folderDeleting" @click="confirmRemoveFolder">{{folderDeleteMode==='delete'?'永久删除':'删除并保留图片'}}</n-button></div></template>
    </n-modal>
    <n-modal v-model:show="showCategories" preset="card" title="管理图片分类" class="category-modal"><p class="category-help">分类会成为顶部筛选按钮，与文件夹互不影响。</p><div class="category-editor panel"><n-input v-model:value="categoryForm.name" maxlength="60" show-count placeholder="分类名称" @keyup.enter="saveCategory"/><n-color-picker v-model:value="categoryForm.color" :show-alpha="false"/><n-button type="primary" :loading="categorySaving" @click="saveCategory">{{editingCategoryId?'保存':'创建'}}</n-button><n-button v-if="editingCategoryId" @click="cancelCategoryEdit">取消</n-button></div><div v-if="categories.length" class="category-manager-list"><div v-for="item in categories" :key="item.id"><i :style="{background:item.color||'#3ec9c5'}"/><div><strong>{{item.label}}</strong><small>{{item.image_count}} 张图片</small></div><n-switch :value="Boolean(item.is_active)" size="small" @update:value="toggleCategory(item,$event)"/><n-button size="tiny" @click="editCategory(item)">改名</n-button><n-button size="tiny" type="error" ghost @click="removeCategory(item)">删除</n-button></div></div></n-modal>
    <ShareDialog v-if="shareTarget" v-model:show="showShare" :target-type="shareTarget.type" :target-id="shareTarget.id" :target-title="shareTarget.title"/>
  </section>
</template>
